#include "engine/arrow_crossings.hpp"
#include <fstream>
#include <iostream>
using namespace r62;using namespace core;using namespace studio::arrow_crossings;
int main(){std::ofstream out("work/r44-curves.svg");out<<"<svg xmlns='http://www.w3.org/2000/svg' width='1000' height='700' viewBox='0 0 1000 700'><rect width='1000' height='700' fill='white'/>";
for(int k=0;k<8;++k){Document doc;auto a=arrows::resolvePreset(58,Vec2(40,130),Vec2(230,130),.6);a.arcSagitta=k%2?-65:65;auto b=arrows::resolvePreset(58,Vec2(130,30),Vec2(130,230),.6);b.arcSagitta=k<4?65:-65;if(k>=4){a.begin=Vec2(30,30);a.end=Vec2(230,220);a.arcSagitta=40;b.begin=Vec2(210,30);b.end=Vec2(40,210);}if(k%4>=2)std::swap(b.begin,b.end);ObjectId first,last;arrows::addArrow(doc,a,.6,&first);arrows::addArrow(doc,b,.6,&last);auto old=intersections(points(b),points(a));auto e=update(doc);bool ok=false;arrows::ArrowParams p;arrows::readArrow(doc,last,&p,&ok);auto now=intersections(points(p),points(a));auto exact=arrows::encodeArrowParams(p);for(int repeat=0;repeat<5;++repeat){update(doc);arrows::ArrowParams repeated;arrows::readArrow(doc,last,&repeated,&ok);if(exact!=arrows::encodeArrowParams(repeated)){std::cerr<<"repeat changed curve";return 4;}}auto withoutRoute=p;withoutRoute.route.clear();if(arrows::encodeArrowParams(withoutRoute)!=arrows::encodeArrowParams(b)){std::cerr<<"arrow style changed";return 5;}arrows::ArrowParams untouched;arrows::readArrow(doc,first,&untouched,&ok);if(!e.ok()||p.route.size()!=129||length(p.begin-b.begin)>1e-9||length(p.end-b.end)>1e-9||arrows::encodeArrowParams(a)!=arrows::encodeArrowParams(untouched)){std::cerr<<"failed "<<k<<" route "<<p.route.size();return 1;}auto sampled=points(p);double positive=0,negative=0;for(size_t i=1;i+1<sampled.size();++i){double side=cross(p.end-p.begin,sampled[i]-p.begin);positive=std::max(positive,side);negative=std::max(negative,-side);if(dot(unit(sampled[i]-sampled[i-1]),unit(sampled[i+1]-sampled[i]))<.99){std::cerr<<"kink "<<k;return 2;}}if(positive<1||negative<1||std::max(positive,negative)/std::min(positive,negative)>=3){std::cerr<<"imbalance "<<k<<" "<<positive<<" "<<negative;return 3;}std::cout<<k<<" crossings "<<old.size()<<" -> "<<now.size()<<" shift "<<length(old.front().point-now.front().point)<<" angle "<<std::acos(std::min(1.,std::abs(dot(now.front().direction,now.front().other))))*180/3.141592653589793<<"\n";out<<"<g transform='translate("<<(k%3)*330<<","<<(k/3)*340<<")'>";auto draw=[&](const std::vector<Vec2>& pts,const char* color,const char* dash){out<<"<polyline fill='none' stroke='"<<color<<"' stroke-width='2' "<<dash<<" points='";for(auto q:pts)out<<q.x<<","<<q.y<<" ";out<<"'/>";};draw(points(a),"black","");draw(points(b),"#bbb","stroke-dasharray='4 4'");draw(points(p),"#1767be","");out<<"</g>";}out<<"</svg>";}
